package com.bautruc.ecommerce.chat.api;
import com.bautruc.ecommerce.chat.api.request.ChatMessageRequest;import com.bautruc.ecommerce.chat.application.ChatService;import com.bautruc.ecommerce.common.logging.LogContext;import com.bautruc.ecommerce.common.response.ApiResponse;import com.bautruc.ecommerce.common.time.BusinessClock;import jakarta.servlet.http.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/chat") public class ChatController {private final ChatService chat;private final BusinessClock clock;public ChatController(ChatService chat,BusinessClock clock){this.chat=chat;this.clock=clock;}@GetMapping("/session")public ApiResponse<ChatService.ThreadView> session(@CookieValue(value="BT_CHAT",required=false)String cookie){return ok(chat.mine(cookie));}@PostMapping("/messages")public ApiResponse<ChatService.ThreadView> send(@CookieValue(value="BT_CHAT",required=false)String cookie,@Valid @RequestBody ChatMessageRequest req,HttpServletResponse response){var r=chat.send(cookie,req);if(r.newGuestToken()!=null)response.addHeader(HttpHeaders.SET_COOKIE,ResponseCookie.from("BT_CHAT",r.newGuestToken()).httpOnly(true).sameSite("Lax").path("/").maxAge(java.time.Duration.ofDays(60)).build().toString());return ok(r.thread());}@PatchMapping("/close")public ApiResponse<ChatService.ThreadView> close(@CookieValue(value="BT_CHAT",required=false)String cookie){return ok(chat.closeMine(cookie));}private <T>ApiResponse<T> ok(T d){return ApiResponse.success(d,null,clock.businessNow().toOffsetDateTime(),LogContext.currentCorrelationId());}}
